
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_b97_1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_b97_1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.475570523653633e+00, -3.409926124912253e+00, -3.317982649206952e+00, -3.190713543474164e+00, -3.017526513196107e+00, -2.787611477650624e+00, -2.493161999005864e+00, -2.135295603170643e+00, -1.731829852280081e+00, -1.316696248496803e+00, -8.979533243666754e-01, -6.018179217197641e-01, -5.205222684248941e-01, -4.287687871963963e-01, -3.096950497350262e-01, -1.921959894936785e-01, -1.098348695732528e-01, -4.773395511918004e-02, -1.136072894522949e-02, -1.325349302311856e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


